import type { GameLocale } from '../types/i18n'

export const GAME_DEFAULT_LOCALE: GameLocale = 'fr'

export const GAME_LOCALE_OPTIONS: Array<{ id: GameLocale; label: string; tag: string }> = [
  { id: 'fr', label: 'Français', tag: 'fr-FR' },
  { id: 'en', label: 'English', tag: 'en-GB' },
  { id: 'de', label: 'Deutsch', tag: 'de-DE' },
  { id: 'nl', label: 'Nederlands', tag: 'nl-NL' },
  { id: 'es', label: 'Español', tag: 'es-ES' },
  { id: 'it', label: 'Italiano', tag: 'it-IT' },
  { id: 'pt', label: 'Português', tag: 'pt-PT' },
  { id: 'pl', label: 'Polski', tag: 'pl-PL' },
]

export function isGameLocale(value: unknown): value is GameLocale {
  return GAME_LOCALE_OPTIONS.some(option => option.id === value)
}

export function gameLocaleTag(locale: GameLocale) {
  return GAME_LOCALE_OPTIONS.find(option => option.id === locale)?.tag ?? 'fr-FR'
}

export function currentGameLocale(): GameLocale {
  if (typeof document !== 'undefined') {
    const documentLocale = document.documentElement.dataset.cluGameLocale
    if (isGameLocale(documentLocale)) return documentLocale
  }
  if (typeof localStorage !== 'undefined') {
    try {
      const raw = localStorage.getItem('clu-metropole-user-settings-v1')
      const locale = raw ? (JSON.parse(raw) as { locale?: unknown }).locale : null
      if (isGameLocale(locale)) return locale
    }
    catch { /* Préférence absente ou invalide : français. */ }
  }
  return GAME_DEFAULT_LOCALE
}

export function currentGameLocaleTag() {
  return gameLocaleTag(currentGameLocale())
}

